const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=(v='')=>String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}, write=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
const names={home:'工作台',resources:'资源库',recent:'最近使用',favorites:'我的收藏',collections:'集合',taxonomy:'分类与标签',publications:'发布中心',health:'资源健康',smart:'智能视图',connect:'飞书连接'};
const empty=()=>({records:[],schema:[]});
const roleDefs={title:['资源名称','名称','标题','资源标题'],number:['资源编号','编号'],category:['分类','资源分类'],tags:['标签'],status:['资源状态','状态'],cover:['资源封面','封面图片','封面图','封面','资源图片','图片','主图'],url:['资源链接','网盘链接'],description:['简介','描述'],drive:['网盘平台','网盘','存储平台'],updated:['更新时间','最后更新时间','更新日期','修改时间'],platform:['发布平台','平台'],publicationResource:['关联资源','资源'],publicationStatus:['发布状态','状态']};
const state={page:'resources',data:{resources:empty(),categories:empty(),platforms:empty(),publications:empty()},config:read('frm_config',{}),demo:location.protocol==='file:',query:'',category:'',status:'',platform:'',tag:'',layout:'grid',pageNo:1,loading:false,saving:false,lastSync:null,lastAttempt:0,syncError:'',editor:null,credentials:read('frm_credentials',{appId:'',appSecret:''}),favorites:read('frm_favorites',[]),recent:read('frm_recent',[]),collections:read('frm_collections',[{id:'col_week',name:'本周待发布',desc:'准备在本周处理的资源',items:['demo_r0','demo_r2']},{id:'col_hot',name:'重点资源',desc:'高频使用或需要重点维护的资源',items:['demo_r1']}]),smartFilter:'',quickFilter:''};
function raw(v){if(v==null)return '';if(Array.isArray(v))return v.map(raw).filter(Boolean).join('、');if(typeof v==='object')return v.text||v.name||v.link||v.url||v.record_ids?.join('、')||'';return String(v)}
function safeUrl(v){const s=typeof v==='object'&&!Array.isArray(v)?v?.link||v?.url||v?.tmp_url||'':raw(v);try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
function attachmentItem(v){if(Array.isArray(v))return v.find(x=>x&&typeof x==='object'&&(x.file_token||x.url||x.tmp_url))||null;if(v&&typeof v==='object'&&(v.file_token||v.url||v.tmp_url))return v;return null}
function coverSource(v){const a=attachmentItem(v);if(a?.file_token)return{token:String(a.file_token)};const url=safeUrl(a||v);return url?{url}:null}
function hasCover(v){return Boolean(coverSource(v))}
const mediaCache=new Map();
function mediaContext(record,kind='resources'){const schema=state.data[kind]?.schema||[];const mapped=role('cover',kind);let f=schema.find(x=>x.field_name===mapped);if(!f)f=schema.find(x=>x.type===17&&/(封面|图片|主图)/.test(x.field_name||''));if(!f)f=schema.find(x=>x.type===17);const c=state.config[kind];return record&&f&&c?{appToken:c.appToken||'',tableId:c.tableId||'',fieldId:f.field_id||'',recordId:record.record_id||''}:null}
async function hydrateImages(){if(state.demo)return;const imgs=$$('img[data-feishu-token]');await Promise.allSettled(imgs.map(async img=>{const t=img.dataset.feishuToken;if(!t)return;const ctx={app_token:img.dataset.appToken||'',table_id:img.dataset.tableId||'',field_id:img.dataset.fieldId||'',record_id:img.dataset.recordId||''};if(!ctx.app_token||!ctx.table_id||!ctx.field_id||!ctx.record_id){img.classList.add('cover-load-failed');img.title='封面附件上下文缺失：请确认封面字段映射为“资源封面”，然后重新同步';return}const q=new URLSearchParams({file_token:t,...ctx});const key=[t,img.dataset.tableId,img.dataset.fieldId,img.dataset.recordId].join('|');if(mediaCache.has(key)){img.src=mediaCache.get(key);img.removeAttribute('data-feishu-token');return}try{const r=await fetch('/api/media?'+q,{headers:{'x-feishu-app-id':state.credentials.appId||'','x-feishu-app-secret':state.credentials.appSecret||''},signal:AbortSignal.timeout(25000)});if(!r.ok){let msg='';try{msg=(await r.json()).message||''}catch{}throw new Error(msg||'封面读取失败')}const b=await r.blob();if(!b.type.startsWith('image/'))throw new Error('附件不是图片');const u=URL.createObjectURL(b);mediaCache.set(key,u);img.src=u;img.removeAttribute('data-feishu-token')}catch(e){img.classList.add('cover-load-failed');img.title=e.message||'封面读取失败'}}))}
function coverImg(v,alt='',ctx=null){const c=coverSource(v);if(!c)return '';if(c.url)return `<img src="${esc(c.url)}" alt="${esc(alt)}" loading="lazy" referrerpolicy="no-referrer">`;const data=ctx?` data-app-token="${esc(ctx.appToken)}" data-table-id="${esc(ctx.tableId)}" data-field-id="${esc(ctx.fieldId)}" data-record-id="${esc(ctx.recordId)}"`:'';return `<img src="data:image/gif;base64,R0lGODlhAQABAAAAACw=" data-feishu-token="${esc(c.token)}"${data} alt="${esc(alt)}" loading="lazy">`}
function role(key,kind='resources'){const schema=state.data[kind].schema;return (!state.demo&&state.config.mapping?.[kind]?.[key])||roleDefs[key]?.find(n=>schema.some(f=>f.field_name===n))||''}
function fieldValue(r,key,kind='resources'){return r.fields?.[role(key,kind)]}
function relationIds(v){return Array.isArray(v)?v.map(x=>typeof x==='string'?x:x.record_id).filter(Boolean):v?.record_ids||[]}
function relatedKind(f){return Object.keys(state.data).find(k=>state.config[k]?.tableId===f?.property?.table_id)||({demo_categories:'categories',demo_platforms:'platforms',demo_resources:'resources'})[f?.property?.table_id]}
function label(r,kind='resources'){const schema=state.data[kind].schema;return raw(r.fields?.[role('title',kind)])||raw(r.fields?.[schema.find(f=>f.is_primary)?.field_name])||raw(r.fields?.名称)||raw(Object.values(r.fields||{})[0])||'未命名'}
function display(v,f){if([18,21].includes(f?.type)){const kind=relatedKind(f);return relationIds(v).map(id=>{const r=state.data[kind]?.records.find(x=>x.record_id===id);return r?label(r,kind):id}).join('、')}if(f?.type===5&&v)return new Date(Number(v)).toLocaleString('zh-CN');if(f?.type===7)return v?'是':'否';return raw(v)}
function value(r,key,kind='resources'){return display(fieldValue(r,key,kind),state.data[kind].schema.find(f=>f.field_name===role(key,kind)))}
function demoData(){const f=(name,type=1,property={})=>({field_name:name,type,property});const cats=['游戏 / 安卓单机','软件 / 效率工具','AI / 提示词','资料 / 电子书','设计 / 素材','学习 / 教程'];const names=['安卓单机游戏合集','办公效率工具集','AI 绘画提示词库','个人成长电子书','社交媒体设计素材','摄影入门课程','经典像素游戏','电脑实用工具箱','人像摄影提示词','职场实用资料','海报排版模板','英语学习课程'];return {categories:{schema:[{...f('名称'),is_primary:true},f('排序',2),f('备注')],records:cats.map((n,i)=>({record_id:`demo_c${i}`,fields:{名称:n,排序:i+1,备注:'可自由添加分类'}}))},platforms:{schema:[{...f('名称'),is_primary:true},f('排序',2)],records:['闲鱼','小红书','X','抖音','Telegram'].map((n,i)=>({record_id:`demo_p${i}`,fields:{名称:n,排序:i+1}}))},resources:{schema:[{...f('资源名称'),is_primary:true},f('资源编号'),f('分类',18,{table_id:'demo_categories'}),f('标签',4),f('资源状态',3,{options:['正常','待更新','失效'].map(name=>({name}))}),f('封面图片',15),f('网盘平台',3,{options:['夸克网盘','百度网盘','阿里云盘'].map(name=>({name}))}),f('资源链接',15),f('提取码'),f('简介'),f('备注'),f('更新时间',5)],records:names.map((n,i)=>({record_id:`demo_r${i}`,fields:{资源名称:n,资源编号:`VR-${String(i+1).padStart(5,'0')}`,分类:i===10?[]:[`demo_c${i%6}`],标签:i===8?[]:[['安卓','效率','AI','阅读','设计','学习'][i%6],'合集'],资源状态:i===3?'失效':i%4===0?'待更新':'正常',网盘平台:i%3===0?'百度网盘':'夸克网盘',简介:i===9?'':'演示资料，用于体验资源整理、收藏、集合、发布与健康检查。',资源链接:i===7?'':{text:'示例链接',link:'https://example.com'},更新时间:Date.now()-i*86400000*7}}))},publications:{schema:[{...f('标题'),is_primary:true},f('关联资源',18,{table_id:'demo_resources'}),f('发布平台',18,{table_id:'demo_platforms'}),f('发布状态',3,{options:['待发布','已发布','待更新','已下架'].map(name=>({name}))}),f('发布文案'),f('发布链接',15)],records:[0,1,2,4,5,6,8].map((i,n)=>({record_id:`demo_pub${n}`,fields:{标题:`${names[i]} · ${['X','闲鱼','小红书','抖音'][n%4]}`,关联资源:[`demo_r${i}`],发布平台:[`demo_p${[2,0,1,3,4,0,1][n]}`],发布状态:n%3===0?'待发布':n%3===1?'已发布':'待更新',发布文案:'演示发布记录'}}))}}}
async function req(path,opt={}){let res;try{res=await fetch(path,{...opt,headers:{'content-type':'application/json','x-feishu-app-id':state.credentials.appId||'','x-feishu-app-secret':state.credentials.appSecret||'',...opt.headers},signal:AbortSignal.timeout(25000)})}catch{const e=new Error(opt.method&&opt.method!=='GET'?'网络中断，写入结果尚未确认。请先同步确认。':'网络连接失败，请稍后重试');e.uncertain=Boolean(opt.method&&opt.method!=='GET');throw e}let d;try{d=await res.json()}catch{throw new Error('服务返回异常，请确认通过 Cloudflare Worker 运行')}if(!res.ok)throw new Error(d.message||`请求失败 ${res.status}`);return d}
function endpoint(kind,sub='records'){const c=state.config[kind];if(!c?.appToken||!c.tableId)throw new Error(`请先连接${names[kind]||kind}`);return `/api/table/${sub}?`+new URLSearchParams({app_token:c.appToken,table_id:c.tableId})}
async function fetchTable(kind,config=state.config){const c=config[kind];if(!c)return empty();const qs=new URLSearchParams({app_token:c.appToken,table_id:c.tableId});const [r,s]=await Promise.all([req(`/api/table/records?${qs}`),req(`/api/table/fields?${qs}`)]);return{records:r.items,schema:s.items}}
async function load({quiet=false}={}){if(state.loading||state.saving||state.editor)return;if(state.demo){if(!state.data.resources.schema.length)state.data=read('frm_demo_v5',null)||demoData();render();return}if(!state.config.resources){render();return}state.loading=true;state.lastAttempt=Date.now();state.syncError='';syncUI();try{const entries=await Promise.all(Object.keys(state.data).map(async k=>[k,await fetchTable(k)]));state.data=Object.fromEntries(entries);state.lastSync=new Date();if(!quiet)notice('已从飞书读取最新数据')}catch(e){state.syncError=e.message;notice(e.message,true)}finally{state.loading=false;render()}}
function syncUI(){const text=state.demo?'演示模式 · 本机保存':state.loading?'正在读取飞书…':state.syncError?'同步失败':state.lastSync?`同步于 ${state.lastSync.toLocaleTimeString('zh-CN')}`:'尚未连接';$('#syncStatus').textContent=text;$('#sideStatus').textContent=state.demo?'演示空间':state.lastSync&&!state.syncError?'飞书已连接':'等待连接';$('#refresh').disabled=state.loading||state.saving}
function notice(msg,error=false){const n=$('#notice');n.textContent=msg;n.className=`notice${error?' error':''}`;clearTimeout(notice.t);notice.t=setTimeout(()=>n.classList.add('hidden'),2600)}
function nav(page){if(!names[page])return;state.page=page;state.query='';state.category='';state.status='';state.platform='';state.tag='';state.smartFilter='';state.quickFilter='';state.pageNo=1;render()}
function heading(title,desc,action=''){return `<div class="heading"><div><div class="eyebrow">RESOURCE HUB</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><div class="page-actions">${action}</div></div>`}
function badge(s){return `<span class="status ${/正常|已发布|可用/.test(s)?'ok':/失效|下架/.test(s)?'bad':/待|草稿/.test(s)?'warn':''}">${esc(s||'未设置')}</span>`}
function categoryNames(){const r=state.data.resources,f=r.schema.find(f=>f.field_name===role('category'));return [...new Set([...[...state.data.categories.records].sort((a,b)=>Number(a.fields.排序||0)-Number(b.fields.排序||0)).map(r=>label(r,'categories')),...(f?.property?.options||[]).map(o=>o.name),...r.records.map(r=>value(r,'category')).filter(Boolean)])]}
function platformFor(r){return state.data.publications.records.filter(p=>relationIds(fieldValue(p,'publicationResource','publications')).includes(r.record_id)).map(p=>value(p,'platform','publications')).join('、')||value(r,'platform')}
function tagsOf(r){return raw(fieldValue(r,'tags')).split('、').map(x=>x.trim()).filter(Boolean)}
function findResourceField(names=[],pattern=null){const schema=state.data.resources.schema||[];return schema.find(f=>names.includes(f.field_name))||schema.find(f=>pattern?.test(f.field_name||''))||null}
function splitValues(v){if(Array.isArray(v))return v.map(raw).filter(Boolean);return raw(v).split(/[、,，]/).map(x=>x.trim()).filter(Boolean)}
function publicationStatusField(){return findResourceField(['发布状态','平台发布状态'],/发布.*状态|状态.*发布/)}
function linkStatusField(){return findResourceField(['网盘链接状态','链接状态','资源链接状态'],/网盘.*状态|链接.*状态/)}
function quarkField(){return findResourceField(['夸克网盘链接','夸克链接'],/夸克.*链接/)}
function baiduField(){return findResourceField(['百度网盘链接','百度链接'],/百度.*链接/)}
function publicationValues(r){const f=publicationStatusField();return f?splitValues(r.fields?.[f.field_name]):platformFor(r).split('、').filter(Boolean)}
function quickMatch(r,key){if(key==='xiaohongshu')return publicationValues(r).includes('🍠 小红书 ✅');if(key==='xianyu')return publicationValues(r).includes('🐟 咸鱼 ✅');if(key==='twitter')return publicationValues(r).includes('𝕏 Twitter ✅');if(key==='quark'){const f=quarkField();return Boolean(f&&safeUrl(r.fields?.[f.field_name])||f&&raw(r.fields?.[f.field_name]).trim())}if(key==='baidu'){const f=baiduField();return Boolean(f&&safeUrl(r.fields?.[f.field_name])||f&&raw(r.fields?.[f.field_name]).trim())}return true}
function quickLabel(key){return({xiaohongshu:'小红书',xianyu:'闲鱼',twitter:'X',quark:'夸克网盘',baidu:'百度网盘'})[key]||''}
function filterOptions(field,fallback=[]){const opts=(field?.property?.options||[]).map(o=>o.name).filter(Boolean);const values=field?state.data.resources.records.flatMap(r=>splitValues(r.fields?.[field.field_name])):fallback;return [...new Set([...opts,...values].filter(Boolean))]}
function healthIssues(r){const out=[];if(!value(r,'category'))out.push('无分类');if(!tagsOf(r).length)out.push('无标签');if(!hasCover(fieldValue(r,'cover')))out.push('无封面');if(!safeUrl(fieldValue(r,'url')))out.push('无链接');if(/失效/.test(value(r,'status')))out.push('链接失效');if(/待更新/.test(value(r,'status')))out.push('待更新');const u=fieldValue(r,'updated');if(u&&Date.now()-Number(u)>1000*60*60*24*90)out.push('长期未更新');return out}
function filtered(){return state.data.resources.records.filter(r=>{const hay=Object.entries(r.fields).map(([k,v])=>display(v,state.data.resources.schema.find(f=>f.field_name===k))).join(' ').toLowerCase();const cv=value(r,'category');const catOk=!state.category||(state.category==='__none'?!cv:cv.split('、').some(x=>x===state.category||x.startsWith(state.category+' / ')));const smartOk=!state.smartFilter||healthIssues(r).includes(state.smartFilter)||state.smartFilter==='从未发布'&&!platformFor(r)||state.smartFilter==='收藏'&&state.favorites.includes(r.record_id);const linkField=linkStatusField();const statusValues=linkField?splitValues(r.fields?.[linkField.field_name]):[value(r,'status')];const pubValues=publicationValues(r);return (!state.query||hay.includes(state.query.toLowerCase()))&&catOk&&(!state.status||statusValues.includes(state.status))&&(!state.platform||pubValues.includes(state.platform)||platformFor(r).split('、').includes(state.platform))&&(!state.tag||tagsOf(r).includes(state.tag))&&smartOk&&(!state.quickFilter||quickMatch(r,state.quickFilter))})}
function select(id,title,values,current){return `<select id="${id}"><option value="">${title}</option>${[...new Set(values.filter(Boolean))].map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('')}</select>`}
function card(r){const cover=coverImg(fieldValue(r,'cover'),label(r),mediaContext(r));const cat=value(r,'category')||'未分类',drive=value(r,'drive')||'',i=[...cat].reduce((n,c)=>n+c.codePointAt(0),0)%6;const fav=state.favorites.includes(r.record_id);return `<article class="card"><div class="cover tone-${i}" data-detail="${esc(r.record_id)}" data-kind="resources">${cover||`<span class="cover-index">${esc(value(r,'number')||'RESOURCE')}</span><strong>${esc(cat.split(' / ').at(-1))}</strong>`}${drive?`<span class="cover-drive">${esc(drive)}</span>`:''}<button class="fav ${fav?'on':''}" data-action="favorite" data-id="${esc(r.record_id)}" aria-label="收藏">★</button></div><div class="card-body"><span class="card-category">${esc(cat)}</span><h3 data-detail="${esc(r.record_id)}" data-kind="resources">${esc(label(r))}</h3><div class="card-meta"><span>${esc(value(r,'number')||'未编号')}</span>${badge(value(r,'status'))}</div></div></article>`}
function miniCard(r){const cover=coverImg(fieldValue(r,'cover'),label(r),mediaContext(r));return `<button class="mini-card" data-detail="${esc(r.record_id)}" data-kind="resources"><div class="mini-cover">${cover||esc((value(r,'category')||'资源').split(' / ').at(-1))}</div><div class="mini-body"><b>${esc(label(r))}</b><small>${esc(value(r,'number')||value(r,'category')||'资源')}</small></div></button>`}
function table(kind,rows){const schema=state.data[kind].schema;const columns=kind==='resources'?[role('title'),role('category'),role('number'),role('status')].filter(Boolean):schema.slice(0,5).map(f=>f.field_name);return `<div class="table-wrap panel"><table><thead><tr>${columns.map(c=>`<th>${esc(c)}</th>`).join('')}<th>操作</th></tr></thead><tbody>${rows.map(r=>`<tr>${columns.map(c=>`<td>${esc(display(r.fields[c],schema.find(f=>f.field_name===c)))||'—'}</td>`).join('')}<td><button class="text-btn" data-detail="${esc(r.record_id)}" data-kind="${kind}">查看</button></td></tr>`).join('')}</tbody></table></div>`}
function emptyView(title,desc){return `<div class="empty"><h3>${esc(title)}</h3><p>${esc(desc)}</p>${!state.config.resources&&!state.demo?'<button class="btn primary" data-nav="connect">连接飞书</button> <button class="btn" data-action="demo">体验演示</button>':''}</div>`}
function resources(){const rows=filtered(),cats=categoryNames();state.pageNo=Math.min(state.pageNo,Math.max(1,Math.ceil(rows.length/25)));const pageRows=rows.slice((state.pageNo-1)*25,state.pageNo*25);const statusField=linkStatusField()||findResourceField([role('status')].filter(Boolean),/资源.*状态|状态/);const platformField=publicationStatusField();const statusOptions=filterOptions(statusField,state.data.resources.records.map(r=>value(r,'status')));const platformOptions=filterOptions(platformField,[...state.data.platforms.records.map(r=>label(r,'platforms')),...state.data.resources.records.flatMap(r=>platformFor(r).split('、'))]);const categoryBar=`<div class="category-strip panel"><span class="category-strip-label">分类</span><button class="category-chip ${!state.category?'active':''}" data-category="">全部资源 <small>${state.data.resources.records.length}</small></button>${cats.map(c=>`<button class="category-chip ${state.category===c?'active':''}" data-category="${esc(c)}">${esc(c)}</button>`).join('')}<button class="category-chip ${state.category==='__none'?'active':''}" data-category="__none">未分类</button></div>`;const quick=state.quickFilter?`<div class="active-filter panel"><span>当前快捷筛选：<b>${esc(quickLabel(state.quickFilter))}</b></span><button class="text-btn" data-action="clear-quick-filter">清除</button></div>`:'';return categoryBar+quick+`<div class="resource-content"><div class="filterbar panel"><input id="search" type="search" value="${esc(state.query)}" placeholder="搜索名称、编号、标签、描述…">${select('statusFilter','全部状态',statusOptions,state.status)}${select('platformFilter','全部平台',platformOptions,state.platform)}</div><div class="section-row"><span><b>${rows.length}</b> 条资源</span><div class="segmented"><button data-layout="grid" class="${state.layout==='grid'?'active':''}">卡片</button><button data-layout="table" class="${state.layout==='table'?'active':''}">列表</button></div></div>${rows.length?(state.layout==='grid'?`<div class="grid">${pageRows.map(card).join('')}</div>`:table('resources',pageRows)):emptyView('没有符合条件的资源','调整筛选条件后再试。')}<div class="pagination"><span>每页 25 条</span><button class="btn" data-turn="-1" ${state.pageNo<=1?'disabled':''}>上一页</button><span>${state.pageNo} / ${Math.max(1,Math.ceil(rows.length/25))}</span><button class="btn" data-turn="1" ${state.pageNo*25>=rows.length?'disabled':''}>下一页</button></div></div>`}
function home(){const rs=state.data.resources.records,recent=state.recent.map(id=>rs.find(r=>r.record_id===id)).filter(Boolean).slice(0,6),fav=state.favorites.map(id=>rs.find(r=>r.record_id===id)).filter(Boolean).slice(0,6);const issues=['链接失效','待更新','无封面','无分类'].map(n=>[n,rs.filter(r=>healthIssues(r).includes(n)).length]);return heading('工作台','从最近使用、待处理和常用资源开始一天的管理。')+`<div class="metric-strip"><div class="metric panel"><span>资源总数</span><b>${rs.length}</b><small>当前资源库</small></div><div class="metric panel"><span>待处理</span><b>${rs.filter(r=>healthIssues(r).length).length}</b><small>至少存在一个健康问题</small></div><div class="metric panel"><span>收藏</span><b>${state.favorites.length}</b><small>高频资源</small></div><div class="metric panel"><span>发布记录</span><b>${state.data.publications.records.length}</b><small>全部平台</small></div></div><div class="home-grid"><div><section class="section panel"><div class="section-head"><h2>最近使用</h2><button class="text-btn" data-nav="recent">查看全部</button></div>${recent.length?`<div class="mini-grid">${recent.map(miniCard).join('')}</div>`:emptyView('还没有最近记录','打开资源后会自动出现在这里。')}</section><section class="section panel"><div class="section-head"><h2>我的收藏</h2><button class="text-btn" data-nav="favorites">查看全部</button></div>${fav.length?`<div class="mini-grid">${fav.map(miniCard).join('')}</div>`:emptyView('还没有收藏','点击资源封面右上角的星标即可收藏。')}</section></div><div><section class="section panel"><div class="section-head"><h2>待处理</h2><button class="text-btn" data-nav="health">资源健康</button></div><div class="todo-list">${issues.map(([n,c])=>`<button class="todo" data-health="${esc(n)}"><span><strong>${esc(n)}</strong><span> · 点击处理</span></span><b>${c}</b></button>`).join('')}</div></section><section class="section panel"><div class="section-head"><h2>快捷操作</h2></div><div class="quick-grid"><button class="quick" data-action="new" data-kind="resources">＋ 新增资源</button><button class="quick" data-nav="collections">▤ 新建集合</button><button class="quick" data-nav="publications">↗ 发布中心</button><button class="quick" data-nav="connect">⚙ 飞书连接</button></div></section></div></div>`}
function resourceSetPage(title,desc,ids){const rows=ids.map(id=>state.data.resources.records.find(r=>r.record_id===id)).filter(Boolean);return heading(title,desc)+ (rows.length?`<div class="grid">${rows.map(card).join('')}</div>`:emptyView(title==='我的收藏'?'还没有收藏':'还没有最近使用记录',title==='我的收藏'?'在资源卡片上点击星标，把常用资源放到这里。':'打开任意资源后，会自动记录到这里。'))}
function collections(){return heading('集合','把不同分类的资源临时或长期放进一个工作集合。',`<button class="btn primary" data-action="new-collection">＋ 新建集合</button>`)+`<div class="collection-list">${state.collections.map(c=>`<button class="collection panel" data-collection="${esc(c.id)}"><h3>${esc(c.name)}</h3><p>${esc(c.desc||'自定义资源集合')}</p><div class="collection-foot"><span>${c.items.length} 个资源</span><span>打开 →</span></div></button>`).join('')}</div>`}
function taxonomy(){const cats=categoryNames(),allTags=[...new Set(state.data.resources.records.flatMap(tagsOf))].sort();return heading('分类与标签','分类负责结构，标签负责特征；两者都用于快速找到资源。',`<button class="btn primary" data-action="new" data-kind="categories">＋ 新建分类</button>`)+`<section class="section panel"><div class="section-head"><h2>分类</h2><span>${cats.length} 个</span></div><div class="entity-grid">${cats.map(c=>{const count=state.data.resources.records.filter(r=>value(r,'category').split('、').some(x=>x===c||x.startsWith(c+' / '))).length;const rec=state.data.categories.records.find(r=>label(r,'categories')===c);return `<button class="entity panel" ${rec?`data-detail="${esc(rec.record_id)}" data-kind="categories"`:`data-category-jump="${esc(c)}"`}><div class="entity-top"><h3>${esc(c)}</h3><span>→</span></div><b>${count}</b><small>条资源</small></button>`}).join('')}</div></section><section class="section panel"><div class="section-head"><h2>标签</h2><span>${allTags.length} 个</span></div><div class="tag-cloud">${allTags.map(t=>`<button class="tag-chip" data-tag-jump="${esc(t)}"># ${esc(t)} · ${state.data.resources.records.filter(r=>tagsOf(r).includes(t)).length}</button>`).join('')}</div></section>`}
function publications(){const pubs=state.data.publications.records,platforms=[...new Set([...state.data.platforms.records.map(r=>label(r,'platforms')),...pubs.map(r=>value(r,'platform','publications'))].filter(Boolean))];const active=state.platform;const rows=active?pubs.filter(r=>value(r,'platform','publications')===active):pubs;const counts=p=>({all:pubs.filter(r=>value(r,'platform','publications')===p).length,published:pubs.filter(r=>value(r,'platform','publications')===p&&value(r,'publicationStatus','publications')==='已发布').length,pending:pubs.filter(r=>value(r,'platform','publications')===p&&/待/.test(value(r,'publicationStatus','publications'))).length});return heading('发布中心','按平台查看已发布、待发布和需要更新的资源。',`<button class="btn primary" data-action="new" data-kind="publications">＋ 新增发布记录</button>`)+`<div class="platform-tabs"><button class="${!active?'active':''}" data-platform-tab="">全部平台</button>${platforms.map(p=>`<button class="${active===p?'active':''}" data-platform-tab="${esc(p)}">${esc(p)}</button>`).join('')}</div><div class="entity-grid">${platforms.slice(0,8).map(p=>{const c=counts(p);return `<button class="entity panel" data-platform-tab="${esc(p)}"><div class="entity-top"><h3>${esc(p)}</h3><span>→</span></div><b>${c.all}</b><small>已发布 ${c.published} · 待处理 ${c.pending}</small></button>`}).join('')}</div><div class="section-row"><span><b>${rows.length}</b> 条发布记录</span></div>${state.data.publications.schema.length?(rows.length?table('publications',rows):emptyView('暂无发布记录','选择其他平台，或新增一条发布记录。')):emptyView('尚未连接发布记录表','在飞书连接页添加发布记录表后，这里会自动显示。')}`}
function health(){const rs=state.data.resources.records,problemRows=rs.filter(r=>healthIssues(r).length),healthy=rs.length-problemRows.length,rate=rs.length?Math.round(healthy/rs.length*100):100,defs=[['链接失效','资源当前不可访问','danger'],['待更新','需要重新检查或补充','warn'],['无封面','缺少卡片视觉封面','warn'],['无分类','尚未归入资源分类','warn'],['无标签','缺少搜索标签','warn'],['无链接','没有可访问的资源地址','danger'],['长期未更新','超过 90 天未维护','warn']];return heading('资源健康','快速查看需要维护的资源，点击问题卡片即可筛选处理。')+`<section class="health-summary panel"><div class="health-score"><div class="health-ring" style="--score:${rate}"><strong>${rate}%</strong></div><div><h2>资源健康度</h2><p>${healthy} 条状态良好 · ${problemRows.length} 条需要处理</p></div></div><div class="health-summary-stats"><div><span>资源总数</span><b>${rs.length}</b></div><div><span>健康资源</span><b class="good">${healthy}</b></div><div><span>待处理</span><b class="bad">${problemRows.length}</b></div></div></section><div class="health-grid health-grid-comfort">${defs.map(([n,d,c])=>{const count=rs.filter(r=>healthIssues(r).includes(n)).length;return `<button class="health-card panel ${c}" data-health="${esc(n)}"><div class="health-card-top"><span>${esc(n)}</span><b>${count}</b></div><p>${esc(d)}</p><small>${count?'点击查看并处理 →':'当前无需处理'}</small></button>`}).join('')}</div><div class="health-list-head"><div><h2>待处理资源</h2><p>显示当前存在至少一个健康问题的资源</p></div><span>${problemRows.length} 条</span></div>${problemRows.length?table('resources',problemRows.slice(0,50)):emptyView('资源状态很好','目前没有检测到需要处理的问题。')}`}
function smart(){const rs=state.data.resources.records,views=[['从未发布','没有任何平台发布记录'],['收藏','你标记为收藏的资源'],['无封面','没有封面图片'],['无分类','没有分类'],['无标签','没有标签'],['无链接','没有资源链接'],['待更新','状态为待更新'],['链接失效','状态为失效']];const saved=read('frm_saved_views',[]);return heading('智能视图','把常用筛选保存成一键入口，不需要重复设置条件。')+`<div class="smart-grid">${views.map(([n,d])=>`<button class="smart-card panel" data-smart="${esc(n)}"><h3>${esc(n)}</h3><p>${esc(d)}</p><b>${n==='收藏'?state.favorites.length:rs.filter(r=>n==='从未发布'?!platformFor(r):healthIssues(r).includes(n)).length} 条</b></button>`).join('')}</div>${saved.length?`<div class="section-row"><span>已保存筛选</span></div><div class="collection-list">${saved.map((v,i)=>`<button class="collection panel" data-saved-view="${i}"><h3>${esc(v.name)}</h3><p>${esc([v.category,v.status,v.platform,v.tag].filter(Boolean).join(' · ')||'全部资源')}</p><div class="collection-foot"><span>自定义视图</span><span>打开 →</span></div></button>`).join('')}</div>`:''}`}
function connection(){return heading('飞书连接','个人简化模式：在网页里填一次飞书应用凭据，再粘贴多维表格链接即可。')+`<div class="connect-grid"><form id="connectForm" class="section panel"><h2>快速连接</h2><div class="form two"><label class="field"><span>飞书 App ID</span><input id="feishuAppId" autocomplete="off" value="${esc(state.credentials.appId||'')}" placeholder="cli_xxxxxxxxx"></label><label class="field"><span>飞书 App Secret</span><input id="feishuAppSecret" type="password" autocomplete="off" value="${esc(state.credentials.appSecret||'')}" placeholder="仅保存在当前浏览器"></label></div><label class="field"><span>资源表链接 · 必填</span><input type="url" data-connect="resources" value="${esc(state.config.resources?.url||'')}" placeholder="粘贴飞书多维表格链接"></label><details class="guide compact"><summary>高级选项（通常不用填写）</summary><label class="field"><span>知识库 Base ID / appToken</span><input id="appTokenOverride" value="${esc(state.config.appTokenOverride||'')}" placeholder="只有 wiki 链接无法自动解析时填写"></label>${['categories','platforms','publications'].map(k=>`<label class="field"><span>${names[k]} · 可选</span><input type="url" data-connect="${k}" value="${esc(state.config[k]?.url||'')}" placeholder="可不填"></label>`).join('')}</details><label class="field"><span>自动同步间隔</span><select id="interval">${[15,30,60,120].map(n=>`<option value="${n}" ${n===(state.config.interval||30)?'selected':''}>${n} 秒</option>`).join('')}</select></label><div class="actions"><button class="btn primary" type="submit">连接飞书</button><button class="btn" type="button" data-action="demo">体验演示</button><button class="btn danger" type="button" data-action="disconnect">清除连接</button></div><p id="connectionResult"></p><p class="hint">App Secret 不会写入 GitHub 源码，只保存在当前浏览器，并通过 HTTPS 发送给你自己的 Worker。</p></form><div><section class="guide panel"><span class="eyebrow">最简单的方式</span><h2>3 项信息即可</h2><p>App ID + App Secret + 资源表链接。无需 MANAGER_TOKEN，也无需 FEISHU_ALLOWED_BASES。</p></section><section class="guide panel"><h2>双向同步</h2><p>网页保存后直接写入飞书；飞书中的变化按同步间隔重新读取。分类、平台和发布记录表仍可在高级选项中按需增加。</p></section></div></div>${mappingPanel()}`}
function mappingPanel(){if(!state.data.resources.schema.length)return '';return `<section class="section panel"><div class="section-head"><h2>字段对应</h2><span>表头不同也能适配</span></div><div class="form">${[['resources',['title','number','category','tags','status','cover','drive','url','description','updated']],['publications',['publicationResource','platform','publicationStatus']]].map(([kind,roles])=>roles.map(key=>`<label class="field"><span>${kind==='resources'?'资源':'发布'} · ${roleDefs[key][0]}</span><select data-map="${kind}:${key}"><option value="">自动识别</option>${state.data[kind].schema.map(f=>`<option value="${esc(f.field_name)}" ${role(key,kind)===f.field_name?'selected':''}>${esc(f.field_name)}</option>`).join('')}</select></label>`).join('')).join('')}</div><button class="btn" data-action="mapping">保存字段对应</button></section>`}
function render(){syncUI();const breadcrumb=$('.breadcrumb');if(state.page==='resources'){breadcrumb.innerHTML='<div class="header-resource-title"><span>RESOURCE HUB</span><strong>资源库</strong></div>'}else{breadcrumb.innerHTML=`资源中控台 <span>/</span> <b id="pageName">${esc(names[state.page])}</b>`}$$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page||Boolean(b.dataset.quickFilter&&state.page==='resources'&&b.dataset.quickFilter===state.quickFilter)));$$('[data-count]').forEach(el=>{const key=el.dataset.count;el.textContent=state.data.resources.records.filter(r=>quickMatch(r,key)).length||''});const views={home,resources,recent:()=>resourceSetPage('最近使用','你最近打开过的资源，按访问顺序排列。',state.recent),favorites:()=>resourceSetPage('我的收藏','把高频、重要和经常分享的资源集中在这里。',state.favorites),collections,taxonomy,publications,health,smart,connect:connection};$('#view').innerHTML=(views[state.page]||resources)();if(!state.demo&&state.credentials.appId&&state.credentials.appSecret)hydrateImages().catch(()=>{})}
function writable(f){return !f.is_computed&&[1,2,3,4,5,7,13,15,17,18,21].includes(f.type)&&(![18,21].includes(f.type)||relatedKind(f))}
function isDriveLinkField(f){return /(?:夸克|百度).*(?:链接|网盘)|(?:链接|网盘).*(?:夸克|百度)/.test(f.field_name||'')}
function multiOptionControl(f,v){const name=esc(f.field_name),opts=f.property?.options||[],selected=Array.isArray(v)?v.map(raw):[raw(v)].filter(Boolean);const summary=selected.length?selected.join('、'):'请选择';return `<div class="multi-select" data-multi-field="${name}"><button type="button" class="multi-select-trigger" data-multi-toggle><span data-multi-summary>${esc(summary)}</span><i>⌄</i></button><div class="multi-select-menu hidden" data-multi-menu>${opts.map(o=>`<label class="multi-select-option"><input type="checkbox" data-multi-option value="${esc(o.name)}" ${selected.includes(o.name)?'checked':''}><span>${esc(o.name)}</span></label>`).join('')}${opts.length?'':'<div class="multi-select-empty">飞书此列暂无选项</div>'}</div><div class="multi-select-chips" data-multi-chips>${selected.map(x=>`<button type="button" class="multi-chip" data-multi-remove="${esc(x)}">${esc(x)} <b>×</b></button>`).join('')}</div><select name="${name}" multiple hidden data-multi-native>${opts.map(o=>`<option value="${esc(o.name)}" ${selected.includes(o.name)?'selected':''}>${esc(o.name)}</option>`).join('')}</select></div><small>支持多项选择；点击已选标签 × 可取消，选项与飞书多选列保持一致</small>`}
function optionControl(f,v){const name=esc(f.field_name),opts=f.property?.options||[],selected=Array.isArray(v)?v.map(raw):[raw(v)].filter(Boolean);if(f.type===4)return multiOptionControl(f,v);return `<select name="${name}"><option value="">未设置</option>${opts.map(o=>`<option value="${esc(o.name)}" ${selected.includes(o.name)?'selected':''}>${esc(o.name)}</option>`).join('')}</select>${/网盘链接状态|发布状态/.test(f.field_name)?'<small>当前飞书字段是单选；如需同时选择多项，请把该列改为“多选”，网页会自动切换为多选下拉。</small>':''}`}
function syncMultiControl(box){if(!box)return;const checked=[...box.querySelectorAll('[data-multi-option]:checked')].map(x=>x.value),native=box.querySelector('[data-multi-native]'),summary=box.querySelector('[data-multi-summary]'),chips=box.querySelector('[data-multi-chips]');if(native)[...native.options].forEach(o=>o.selected=checked.includes(o.value));if(summary)summary.textContent=checked.length?checked.join('、'):'请选择';if(chips)chips.innerHTML=checked.map(x=>`<button type="button" class="multi-chip" data-multi-remove="${esc(x)}">${esc(x)} <b>×</b></button>`).join('')}
function attachmentControl(f,v,r){const tokens=(Array.isArray(v)?v:[]).filter(x=>x?.file_token).map(x=>({file_token:String(x.file_token)}));const ctx=r?.record_id?mediaContext(r):null;const preview=coverImg(v,label(r||{fields:{}},'resources'),ctx);return `<div class="attachment-upload" data-attachment-field="${esc(f.field_name)}"><div class="attachment-preview" data-upload-preview>${preview||'<span>暂无封面</span>'}</div><div class="attachment-tools"><label class="btn upload-btn">选择图片<input type="file" accept="image/*" data-cover-upload="${esc(f.field_name)}" hidden></label><button type="button" class="btn" data-action="paste-cover" data-field="${esc(f.field_name)}">粘贴图片</button><button type="button" class="text-btn danger-text" data-action="clear-cover" data-field="${esc(f.field_name)}">清除</button></div><small>支持本地选择，也支持复制图片后按 Ctrl+V / 点击“粘贴图片”。保存时会上传到飞书并写入当前附件列。</small><input type="hidden" name="${esc(f.field_name)}" value='${esc(JSON.stringify(tokens))}'></div>`}
function control(f,v,r=null){const name=esc(f.field_name),val=raw(v);if(f.type===17)return attachmentControl(f,v,r);if([18,21].includes(f.type)){const k=relatedKind(f),ids=relationIds(v);return `<select name="${name}" multiple>${state.data[k].records.map(r=>`<option value="${esc(r.record_id)}" ${ids.includes(r.record_id)?'selected':''}>${esc(label(r,k))}</option>`).join('')}</select>`}if((f.type===3||f.type===4)&&f.property?.options?.length)return optionControl(f,v);if(f.type===3)return `<select name="${name}"><option value="">未设置</option>${(f.property?.options||[]).map(o=>`<option value="${esc(o.name)}" ${raw(v)===o.name?'selected':''}>${esc(o.name)}</option>`).join('')}</select>`;if(f.type===4)return `<input name="${name}" value="${esc(val)}" placeholder="多个值用、分隔">`;if(f.type===7)return `<input type="checkbox" name="${name}" ${v?'checked':''}>`;if(f.type===2)return `<input type="number" name="${name}" value="${esc(val)}">`;if(f.type===5){const d=v?new Date(Number(v)):null;return `<input type="date" name="${name}" value="${d&&!isNaN(d)?d.toISOString().slice(0,10):''}">`}if(f.type===15){const u=safeUrl(v)||val;const txt=typeof v==='object'&&!Array.isArray(v)?v.text||'':'';const compact=isDriveLinkField(f);return `<div class="url-control ${compact?'compact-url':''}"><input name="${name}" value="${esc(u)}" placeholder="https://…">${compact?'':`<input name="${name}__linktext" value="${esc(txt)}" placeholder="链接文字（可选）">`}</div>`}if(/备注|简介|描述|说明|文案/.test(f.field_name))return `<textarea name="${name}" rows="4">${esc(val)}</textarea>`;return `<input name="${name}" value="${esc(val)}">`}
function formValues(form,schema){const out={};const get=n=>form.elements?.[n]||form.elements?.namedItem?.(n);schema.filter(writable).forEach(f=>{const el=get(f.field_name);if(!el)return;if([18,21].includes(f.type))out[f.field_name]=[...(el.selectedOptions||[])].map(o=>o.value);else if(f.type===17){try{out[f.field_name]=JSON.parse(el.value||'[]')}catch{out[f.field_name]=[]}}else if(f.type===7)out[f.field_name]=Boolean(el.checked);else if(f.type===2)out[f.field_name]=el.value===''?null:Number(el.value);else if(f.type===5){const v=el.value;out[f.field_name]=v?new Date(v.length===10?v+'T12:00:00':v).getTime():null}else if(f.type===4){out[f.field_name]=el.tagName==='SELECT'?[...(el.selectedOptions||[])].map(o=>o.value):el.value.split(/[、,，]/).map(x=>x.trim()).filter(Boolean)}else if(f.type===15){const txt=get(f.field_name+'__linktext')?.value||'';out[f.field_name]=el.value?{link:el.value,text:txt||el.value}:null}else out[f.field_name]=el.value});return out}
let previousFocus=null;function modal(html){previousFocus=document.activeElement;$('#modal').innerHTML=html;$('#overlay').classList.remove('hidden');document.body.style.overflow='hidden';$('#modal').focus()}
function closeModal(force=false){if(state.saving)return;state.editor=null;$('#overlay').classList.add('hidden');document.body.style.overflow='';previousFocus?.focus()}
function addRecent(id){state.recent=[id,...state.recent.filter(x=>x!==id)].slice(0,30);write('frm_recent',state.recent)}
function detail(kind,id){const r=state.data[kind].records.find(x=>x.record_id===id);if(!r)return;if(kind==='resources'){addRecent(id);const schema=state.data.resources.schema;state.editor={kind:'resources',id,revision:r.revision,pendingFiles:{},clearedFields:new Set(),detailEdit:true};modal(`<div class="modalHead"><div><span class="eyebrow">资源信息</span><h2 id="modalTitle">${esc(label(r))}</h2></div><button class="icon" data-action="close">×</button></div><div class="modalBody"><form id="editForm" class="detail-resource-form"><div class="detail-edit-layout"><aside class="detail-media-panel">${detailCoverEditor(r,schema)}<div class="detail-edit-hint"><b>编辑说明</b><br>资源编号保持锁定；其余可写字段可直接修改。分类、发布状态、网盘链接状态等选项会自动读取飞书字段设置。</div></aside><div class="form detail-edit-form">${editorFields('resources',schema,r,{lockNumber:true,excludeCover:true})}</div></div></form><p id="editError"></p></div><div class="modalActions"><button class="btn" data-action="favorite" data-id="${esc(id)}">${state.favorites.includes(id)?'★ 已收藏':'☆ 收藏'}</button><button class="btn danger" data-action="delete" data-kind="resources" data-id="${esc(id)}">删除</button><span class="hint">保存后直接同步到飞书</span><button class="btn" data-action="close">取消</button><button class="btn primary" data-action="save" id="saveButton">保存修改</button></div>`);state.editor.initial=formValues($('#editForm'),schema);hydrateImages();return}state.editor={kind,id,view:true};modal(`<div class="modalHead"><div><span class="eyebrow">${esc(names[kind]||kind)}</span><h2 id="modalTitle">${esc(label(r,kind))}</h2></div><button class="icon" data-action="close">×</button></div><div class="modalBody"><div class="details">${state.data[kind].schema.map(f=>{const v=r.fields[f.field_name];if(v==null||raw(v)==='')return '';const url=safeUrl(v);return `<div class="detailBox"><h3>${esc(f.field_name)}</h3><div>${url?`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(raw(v))} ↗</a>`:esc(display(v,f))}</div></div>`}).join('')}</div></div><div class="modalActions"><button class="btn danger" data-action="delete" data-kind="${kind}" data-id="${esc(id)}">删除</button><button class="btn primary" data-action="edit" data-kind="${kind}" data-id="${esc(id)}">编辑记录</button></div>`)}
function driveLinkGroup(schema,r){const fields=schema.filter(f=>writable(f)&&isDriveLinkField(f));if(!fields.length)return '';return `<div class="field-group full"><div class="field-group-title">网盘链接</div><div class="drive-links-row">${fields.map(f=>{const v=r.fields[f.field_name],url=safeUrl(v);return `<label class="field drive-link-field"><span>${esc(f.field_name)}</span>${control(f,v,r)}${url?`<a class="drive-open-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">打开${esc(f.field_name)} ↗</a>`:'<small class="drive-link-empty">暂无可打开链接</small>'}</label>`}).join('')}</div></div>`}
function editorFields(kind,schema,r,{lockNumber=false,excludeCover=false}={}){const driveFields=new Set(kind==='resources'?schema.filter(f=>writable(f)&&isDriveLinkField(f)).map(f=>f.field_name):[]);const group=kind==='resources'?driveLinkGroup(schema,r):'';const numberField=kind==='resources'?role('number','resources'):'';const coverField=kind==='resources'?role('cover','resources'):'';const rest=schema.filter(writable).filter(f=>!driveFields.has(f.field_name)).filter(f=>!(excludeCover&&coverField&&f.field_name===coverField)).map(f=>{const isNumberLocked=lockNumber&&numberField&&f.field_name===numberField;return `<label class="field ${/备注|简介|描述|说明|文案/.test(f.field_name)||f.type===17?'full':''}"><span>${esc(f.field_name)}${isNumberLocked?' <small class="locked-note">不可修改</small>':''}</span>${isNumberLocked?`<input name="${esc(f.field_name)}" value="${esc(raw(r.fields[f.field_name]))}" readonly class="readonly-field">`:control(f,r.fields[f.field_name],r)}</label>`}).join('');return group+rest}
function detailCoverEditor(r,schema){const fieldName=role('cover','resources');const f=schema.find(x=>x.field_name===fieldName)||schema.find(x=>x.type===17&&/(封面|图片|主图)/.test(x.field_name||''));if(!f)return `<div class="detail-cover detail-cover-empty"><span>暂无封面字段</span></div>`;const v=r.fields[f.field_name],tokens=(Array.isArray(v)?v:[]).filter(x=>x?.file_token).map(x=>({file_token:String(x.file_token)}));const preview=coverImg(v,label(r),mediaContext(r));return `<div class="detail-cover-editor" data-attachment-field="${esc(f.field_name)}"><div class="detail-cover" data-upload-preview>${preview||'<span>暂无封面</span>'}<div class="cover-edit-badge">点击下方按钮修改封面</div></div><div class="detail-cover-actions"><label class="btn primary-soft upload-btn">更换封面<input type="file" accept="image/*" data-cover-upload="${esc(f.field_name)}" hidden></label><button type="button" class="btn" data-action="paste-cover" data-field="${esc(f.field_name)}">粘贴图片</button><button type="button" class="text-btn danger-text" data-action="clear-cover" data-field="${esc(f.field_name)}">清除</button></div><small class="cover-help">支持本地上传或复制图片后直接粘贴，保存时同步到飞书资源封面列。</small><input type="hidden" name="${esc(f.field_name)}" value='${esc(JSON.stringify(tokens))}'></div>`}
function fileToDataUrl(file){return new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(file)})}
async function setPendingCover(field,file){if(!file||!file.type?.startsWith('image/')){notice('请选择图片文件',true);return}if(file.size>20*1024*1024){notice('图片不能超过 20MB',true);return}state.editor.pendingFiles??={};state.editor.pendingFiles[field]=file;state.editor.clearedFields?.delete?.(field);const box=document.querySelector(`[data-attachment-field="${CSS.escape(field)}"] [data-upload-preview]`);if(box){const u=URL.createObjectURL(file);box.innerHTML=`<img src="${u}" alt="待上传封面">`;box.dataset.objectUrl=u}const hidden=$('#editForm')?.elements?.namedItem?.(field);if(hidden)hidden.value='[]'}
function clearPendingCover(field){state.editor.pendingFiles??={};delete state.editor.pendingFiles[field];state.editor.clearedFields??=new Set();state.editor.clearedFields.add(field);const box=document.querySelector(`[data-attachment-field="${CSS.escape(field)}"] [data-upload-preview]`);if(box)box.innerHTML='<span>暂无封面</span>';const hidden=$('#editForm')?.elements?.namedItem?.(field);if(hidden)hidden.value='[]'}
async function uploadAttachment(file,fieldName){const cfg=state.config.resources;if(!cfg?.appToken)throw new Error('资源表尚未连接');const fd=new FormData();fd.append('file',file,file.name||`cover-${Date.now()}.png`);fd.append('app_token',cfg.appToken);fd.append('field_name',fieldName);const r=await fetch('/api/media/upload',{method:'POST',headers:{'x-feishu-app-id':state.credentials.appId||'','x-feishu-app-secret':state.credentials.appSecret||''},body:fd});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||'封面上传失败');if(!d.file_token)throw new Error('封面上传失败：没有返回 file_token');return d.file_token}
function edit(kind,id){if(!state.data[kind].schema.length){notice(`请先连接${names[kind]||kind}`,true);nav('connect');return}const r=id?state.data[kind].records.find(x=>x.record_id===id):{fields:{}};if(!r)return;const schema=state.data[kind].schema;state.editor={kind,id,revision:r.revision,pendingFiles:{},clearedFields:new Set()};modal(`<div class="modalHead"><div><span class="eyebrow">${esc(names[kind]||kind)}</span><h2 id="modalTitle">${id?'编辑':'新增'}记录</h2></div><button class="icon" data-action="close">×</button></div><div class="modalBody"><form id="editForm" class="form">${editorFields(kind,schema,r)}</form><p id="editError"></p></div><div class="modalActions"><span class="hint">${state.demo?'仅保存到演示空间':'保存后直接写入飞书'}</span><button class="btn" data-action="close">取消</button><button class="btn primary" data-action="save" id="saveButton">保存</button></div>`);state.editor.initial=formValues($('#editForm'),schema);hydrateImages()}
async function save(){if(state.saving||!state.editor)return;const {kind,id,revision,initial}=state.editor,form=$('#editForm');if(!form.reportValidity())return;let fields=formValues(form,state.data[kind].schema);const primary=state.data[kind].schema.find(f=>f.is_primary&&writable(f));if(primary&&!fields[primary.field_name]){$('#editError').textContent=`请填写${primary.field_name}`;return}state.saving=true;$('#saveButton').disabled=true;$('#saveButton').textContent='保存中…';try{if(!state.demo&&kind==='resources'){for(const [field,file] of Object.entries(state.editor.pendingFiles||{})){const token=await uploadAttachment(file,field);fields[field]=[{file_token:token}]}}const changes=id?Object.fromEntries(Object.entries(fields).filter(([k,v])=>JSON.stringify(v)!==JSON.stringify(initial[k]))):Object.fromEntries(Object.entries(fields).filter(([,v])=>v!==null));if(id&&!Object.keys(changes).length){state.saving=false;closeModal(true);return}if(state.demo){if(id)Object.assign(state.data[kind].records.find(r=>r.record_id===id).fields,changes);else state.data[kind].records.unshift({record_id:'demo_'+crypto.randomUUID(),fields:changes});write('frm_demo_v5',state.data)}else await req(endpoint(kind)+(id?'&record_id='+encodeURIComponent(id):''),{method:id?'PUT':'POST',body:JSON.stringify({fields:changes,revision})});state.saving=false;closeModal(true);if(!state.demo)await load({quiet:true});else render();notice(state.demo?'已保存到演示空间':'已保存到飞书')}catch(e){state.saving=false;$('#saveButton').disabled=false;$('#saveButton').textContent='保存';$('#editError').textContent=e.message}}
async function remove(kind,id){if(state.saving)return;const record=state.data[kind].records.find(r=>r.record_id===id);if(!record||!confirm(`确定删除「${label(record,kind)}」？`))return;state.saving=true;try{if(state.demo){state.data[kind].records=state.data[kind].records.filter(r=>r.record_id!==id);write('frm_demo_v5',state.data)}else await req(endpoint(kind)+'&record_id='+encodeURIComponent(id),{method:'DELETE',body:JSON.stringify({revision:record.revision})});state.saving=false;closeModal(true);await load({quiet:true});notice('记录已删除')}catch(e){state.saving=false;notice(e.message,true)}}
function toggleFavorite(id){state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[id,...state.favorites];write('frm_favorites',state.favorites);render();if(state.editor?.view)detail('resources',id)}
function newCollection(){const name=prompt('集合名称');if(!name)return;const desc=prompt('集合说明（可选）')||'';state.collections.unshift({id:'col_'+Date.now(),name,desc,items:[]});write('frm_collections',state.collections);render()}
function openCollection(id){const c=state.collections.find(x=>x.id===id);if(!c)return;const rows=c.items.map(id=>state.data.resources.records.find(r=>r.record_id===id)).filter(Boolean);modal(`<div class="modalHead"><div><span class="eyebrow">COLLECTION</span><h2 id="modalTitle">${esc(c.name)}</h2></div><button class="icon" data-action="close">×</button></div><div class="modalBody">${rows.length?`<div class="grid">${rows.map(card).join('')}</div>`:emptyView('集合还是空的','打开资源详情，在“加入集合”中选择它。')}</div><div class="modalActions"><button class="btn danger" data-action="delete-collection" data-id="${esc(c.id)}">删除集合</button></div>`)}
function saveCurrentView(){const name=prompt('给这个筛选起一个名称');if(!name)return;const list=read('frm_saved_views',[]);list.unshift({name,category:state.category,status:state.status,platform:state.platform,tag:state.tag});write('frm_saved_views',list);notice('已保存到智能视图')}
async function connect(e){e.preventDefault();if(location.protocol==='file:'){$('#connectionResult').textContent='本地双击只能体验演示。部署后再连接真实飞书。';return}const appId=$('#feishuAppId').value.trim(),appSecret=$('#feishuAppSecret').value.trim(),appTokenOverride=$('#appTokenOverride')?.value.trim()||'',links=$$('[data-connect]').map(el=>[el.dataset.connect,el.value.trim()]);if(!appId||!appSecret){$('#connectionResult').textContent='请填写飞书 App ID 和 App Secret';return}if(!links.find(([k,v])=>k==='resources'&&v)){$('#connectionResult').textContent='请粘贴资源表链接';return}const oldCredentials={...state.credentials};state.credentials={appId,appSecret};write('frm_credentials',state.credentials);const next={mapping:state.config.mapping||{},interval:Number($('#interval').value),appTokenOverride};state.loading=true;syncUI();try{for(const [k,url]of links)if(url)next[k]=await req('/api/resolve',{method:'POST',body:JSON.stringify({url,appToken:appTokenOverride||undefined})});const data=Object.fromEntries(await Promise.all(Object.keys(state.data).map(async k=>[k,await fetchTable(k,next)])));state.config=next;state.data=data;state.demo=false;state.lastSync=new Date();state.syncError='';write('frm_config',next);notice('飞书连接成功')}catch(err){state.credentials=oldCredentials;write('frm_credentials',oldCredentials);state.syncError=err.message;$('#connectionResult').textContent=err.message}finally{state.loading=false;syncUI();render()}}
$('#nav').onclick=e=>{const b=e.target.closest('[data-page]');if(b)nav(b.dataset.page)};
document.addEventListener('click',e=>{const b=e.target.closest('button,a,[data-detail]');if(!b||b.disabled)return;if(b.dataset.nav){nav(b.dataset.nav);return}if(b.hasAttribute('data-category')){state.category=b.dataset.category;state.pageNo=1;render();return}if(b.dataset.layout){state.layout=b.dataset.layout;render();return}if(b.dataset.turn){state.pageNo+=Number(b.dataset.turn);render();return}if(b.dataset.detail){detail(b.dataset.kind,b.dataset.detail);return}if(b.dataset.health){state.smartFilter=b.dataset.health;state.page='resources';render();return}if(b.dataset.smart){state.smartFilter=b.dataset.smart;state.page='resources';render();return}if(b.hasAttribute('data-platform-tab')){state.platform=b.dataset.platformTab;render();return}if(b.dataset.tagJump){state.page='resources';state.tag=b.dataset.tagJump;render();return}if(b.dataset.categoryJump){state.page='resources';state.category=b.dataset.categoryJump;render();return}if(b.dataset.collection){openCollection(b.dataset.collection);return}if(b.dataset.savedView){const v=read('frm_saved_views',[])[Number(b.dataset.savedView)];if(v){state.page='resources';Object.assign(state,{category:v.category||'',status:v.status||'',platform:v.platform||'',tag:v.tag||''});render()}return}if(b.dataset.quickFilter){state.page='resources';state.quickFilter=b.dataset.quickFilter;state.query='';state.category='';state.status='';state.platform='';state.tag='';state.smartFilter='';state.pageNo=1;render();return}if(b.hasAttribute('data-multi-toggle')){const box=b.closest('[data-multi-field]'),menu=box?.querySelector('[data-multi-menu]');if(menu){document.querySelectorAll('[data-multi-menu]:not(.hidden)').forEach(x=>{if(x!==menu)x.classList.add('hidden')});menu.classList.toggle('hidden')}return}if(b.hasAttribute('data-multi-remove')){const box=b.closest('[data-multi-field]'),value=b.dataset.multiRemove,opt=[...box.querySelectorAll('[data-multi-option]')].find(x=>x.value===value);if(opt)opt.checked=false;syncMultiControl(box);return}const a=b.dataset.action;if(a==='clear-quick-filter'){state.quickFilter='';render();return}if(a==='new')edit(b.dataset.kind);if(a==='edit')edit(b.dataset.kind,b.dataset.id);if(a==='close')closeModal();if(a==='save')save();if(a==='paste-cover'){const field=b.dataset.field;navigator.clipboard?.read?.().then(async items=>{for(const item of items){const type=item.types.find(t=>t.startsWith('image/'));if(type){const blob=await item.getType(type);const file=new File([blob],`pasted-${Date.now()}.${type.split('/')[1]||'png'}`,{type});await setPendingCover(field,file);return}}notice('剪贴板里没有图片',true)}).catch(()=>notice('浏览器未授权读取剪贴板，请直接按 Ctrl+V',true));}if(a==='clear-cover')clearPendingCover(b.dataset.field);if(a==='delete')remove(b.dataset.kind,b.dataset.id);if(a==='favorite')toggleFavorite(b.dataset.id);if(a==='new-collection')newCollection();if(a==='save-view')saveCurrentView();if(a==='toggle-collection-item'){const c=state.collections.find(x=>x.id===b.dataset.collectionId);if(c){c.items=c.items.includes(b.dataset.id)?c.items.filter(x=>x!==b.dataset.id):[...c.items,b.dataset.id];write('frm_collections',state.collections);detail('resources',b.dataset.id)}}if(a==='delete-collection'){state.collections=state.collections.filter(x=>x.id!==b.dataset.id);write('frm_collections',state.collections);closeModal(true);render()}if(a==='demo'){state.demo=true;state.data=read('frm_demo_v5',null)||demoData();notice('已进入演示模式');nav('home')}if(a==='disconnect'&&confirm('断开此浏览器连接？飞书数据不会被删除。')){localStorage.removeItem('frm_config');localStorage.removeItem('frm_credentials');state.config={};state.credentials={appId:'',appSecret:''};state.demo=false;state.data={resources:empty(),categories:empty(),platforms:empty(),publications:empty()};render()}if(a==='mapping'){state.config.mapping={};$$('[data-map]').forEach(el=>{const [k,key]=el.dataset.map.split(':');(state.config.mapping[k]??={})[key]=el.value});write('frm_config',state.config);notice('字段对应已保存');render()}});
// Search input: avoid rebuilding the whole resource view on every keystroke.
// This also fixes cursor jumps and Chinese/Japanese/Korean IME composition issues.
let searchTimer=null,searchComposing=false;
function commitSearchInput(input,{immediate=false}={}){
  state.query=input.value;
  state.pageNo=1;
  if(searchComposing&&!immediate)return;
  clearTimeout(searchTimer);
  const delay=immediate?0:180;
  const start=input.selectionStart??input.value.length;
  const end=input.selectionEnd??start;
  searchTimer=setTimeout(()=>{
    const shouldRefocus=document.activeElement===input;
    render();
    const next=$('#search');
    if(shouldRefocus&&next){
      next.focus({preventScroll:true});
      const a=Math.min(start,next.value.length),b=Math.min(end,next.value.length);
      requestAnimationFrame(()=>{try{next.setSelectionRange(a,b)}catch{}});
    }
  },delay);
}
$('#view').addEventListener('compositionstart',e=>{if(e.target.id==='search')searchComposing=true});
$('#view').addEventListener('compositionend',e=>{if(e.target.id==='search'){searchComposing=false;commitSearchInput(e.target,{immediate:true})}});
$('#view').addEventListener('input',e=>{if(e.target.id==='search')commitSearchInput(e.target)});
$('#view').addEventListener('change',e=>{if(e.target.matches('[data-multi-option]')){syncMultiControl(e.target.closest('[data-multi-field]'));return}const map={statusFilter:'status',platformFilter:'platform'};if(map[e.target.id]){state[map[e.target.id]]=e.target.value;state.pageNo=1;render()}});
document.addEventListener('click',e=>{if(!e.target.closest('[data-multi-field]'))document.querySelectorAll('[data-multi-menu]:not(.hidden)').forEach(x=>x.classList.add('hidden'))});
$('#view').addEventListener('submit',e=>{if(e.target.id==='connectForm')connect(e)});
$('#refresh').onclick=()=>state.editor?notice('请先关闭当前弹窗，再同步'):load();$('#overlay').onclick=e=>{if(e.target===$('#overlay'))closeModal()};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#overlay').classList.contains('hidden'))closeModal()});
document.addEventListener('change',e=>{const input=e.target.closest?.('[data-cover-upload]');if(input?.files?.[0])setPendingCover(input.dataset.coverUpload,input.files[0])});
document.addEventListener('paste',e=>{if(!state.editor||state.editor.kind!=='resources'||!$('#editForm'))return;const item=[...(e.clipboardData?.items||[])].find(x=>x.type?.startsWith('image/'));if(!item)return;const file=item.getAsFile();if(!file)return;const field=state.data.resources.schema.find(f=>f.type===17&&f.field_name===role('cover','resources'))?.field_name||state.data.resources.schema.find(f=>f.type===17)?.field_name;if(field){e.preventDefault();setPendingCover(field,file)}});
setInterval(()=>{if(!document.hidden&&!state.demo&&state.config.resources&&state.page!=='connect'&&!state.editor&&Date.now()-state.lastAttempt>=(state.config.interval||30)*1000)load({quiet:true})},5000);
load();
